(async()=>{
const response=await fetch('/api/inventory',{cache:'no-store'});if(!response.ok)throw Error('No se pudo cargar el catálogo.');const vehicles=await response.json();
const html=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const escaped=v=>Object.fromEntries(Object.entries(v).map(([k,value])=>[k,typeof value==='string'?html(value):value]));
const {renderCards,renderDetail,enhanceSections}=await import('./catalog-experience.js');enhanceSections(vehicles);
const filters=document.querySelector('.filters');filters.innerHTML='<button class="selected" data-filter="all">Todos</button>'+[...new Set(vehicles.map(v=>v.make))].map(make=>'<button data-filter="'+html(make)+'">'+html(make)+'</button>').join('')+'<button data-filter="saved">♡ Favoritos <span id="saved-count">0</span></button>';document.querySelector('.demo-note').textContent='Vehículos disponibles · Consulta precio y disponibilidad.';
let saved;try{saved=JSON.parse(localStorage.getItem('torres-favorites')||'[]');if(!Array.isArray(saved))saved=[];}catch{saved=[];}let currentFilter='all';
const grid=document.querySelector('#vehicle-grid'), search=document.querySelector('#search');
function render(){const query=search.value.trim().toLocaleLowerCase('es');const list=vehicles.filter(v=>(currentFilter==='all'||v.make===currentFilter||(currentFilter==='saved'&&saved.includes(v.id)))&&`${v.make} ${v.name} ${v.year}`.toLocaleLowerCase('es').includes(query));renderCards(list,grid,saved);document.querySelector('#no-results').hidden=list.length!==0;document.querySelector('#saved-count').textContent=saved.filter(id=>vehicles.some(v=>v.id===id)).length;}
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{currentFilter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b===button));render();}));search.addEventListener('input',render);
document.addEventListener('click',event=>{const favorite=event.target.closest('[data-save]');if(favorite){const id=favorite.dataset.save;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];try{localStorage.setItem('torres-favorites',JSON.stringify(saved));}catch{}render();}const car=event.target.closest('[data-car]');if(car)showVehicle(car.dataset.car);});
function showVehicle(id){const raw=vehicles.find(v=>v.id===id);if(!raw)return;renderDetail(raw,document.querySelector('#vehicle-details'));openDialog(document.querySelector('#vehicle-dialog'));document.querySelector('#inquire').onclick=()=>{closeDialog(document.querySelector('#vehicle-dialog'));document.querySelector('[name="interest"]').value='Quiero consultar por un modelo';document.querySelector('[name="message"]').value=`Hola, me interesa el ${raw.make} ${raw.name}. Quisiera conocer su disponibilidad, precio y especificaciones.`;document.querySelector('#contacto').scrollIntoView({behavior:'smooth'});document.querySelector('[name="name"]').focus({preventScroll:true});};}
function openDialog(dialog){dialog.showModal();document.body.style.overflow='hidden';}function closeDialog(dialog){dialog.close();document.body.style.overflow='';}document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.dialog-close').onclick=()=>closeDialog(dialog);dialog.addEventListener('close',()=>document.body.style.overflow='');dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog(dialog);}});});
document.querySelector('#sell-trigger').onclick=()=>{document.querySelector('[name="interest"]').value='Quiero vender mi vehículo';document.querySelector('[name="message"]').value='Hola, quisiera conocer la propuesta de consignación. Mi vehículo es: ';document.querySelector('#contacto').scrollIntoView({behavior:'smooth'});document.querySelector('[name="name"]').focus({preventScroll:true});};
document.querySelector('#contact-form').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);document.querySelector('#prepared-message').value=`Hola, Torres Garage. Soy ${data.get('name').trim()}.\n\n${data.get('interest')}.\n\n${data.get('message').trim()}`;document.querySelector('#copy-status').textContent='';document.querySelector('#copy-message').textContent='Copiar consulta';openDialog(document.querySelector('#message-dialog'));});
document.querySelector('#copy-message').onclick=async()=>{const field=document.querySelector('#prepared-message');try{await navigator.clipboard.writeText(field.value);document.querySelector('#copy-status').textContent='Consulta copiada. Lista para compartir.';document.querySelector('#copy-message').textContent='¡Copiada!';}catch{field.focus();field.select();document.querySelector('#copy-status').textContent='Selecciona y copia el texto de tu consulta.';}};
const menu=document.querySelector('#menu'),navigation=document.querySelector('#navigation');menu.onclick=()=>{const open=navigation.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Cerrar menú':'Abrir menú');menu.textContent=open?'×':'☰';};navigation.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{navigation.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='☰';}));document.querySelector('.search-trigger').onclick=()=>{document.querySelector('#vehiculos').scrollIntoView({behavior:'smooth'});search.focus({preventScroll:true});};
const theme=document.querySelector('#theme'),systemTheme=matchMedia('(prefers-color-scheme: light)');let chosenTheme=null;try{chosenTheme=localStorage.getItem('torres-theme');}catch{}function setTheme(light){document.body.classList.toggle('light',light);document.documentElement.style.colorScheme=light?'light':'dark';theme.setAttribute('aria-label',light?'Activar tema oscuro':'Activar tema claro');theme.setAttribute('aria-pressed',String(light));document.querySelector('meta[name="theme-color"]').content=light?'#f5f6f8':'#080b0d';}setTheme(chosenTheme?chosenTheme==='light':systemTheme.matches);theme.onclick=()=>{const light=!document.body.classList.contains('light');chosenTheme=light?'light':'dark';setTheme(light);try{localStorage.setItem('torres-theme',chosenTheme);}catch{}};systemTheme.addEventListener('change',()=>{if(!chosenTheme)setTheme(systemTheme.matches);});
if('IntersectionObserver'in window){const reveal=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');reveal.unobserve(entry.target);}}),{threshold:.08});document.querySelectorAll('.section-heading,.consign-copy,.about-bottom,.contact>div').forEach(el=>{el.classList.add('reveal');reveal.observe(el);});const navObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){navigation.querySelectorAll('a').forEach(a=>a.classList.toggle('active',a.hash==='#'+entry.target.id));}}),{rootMargin:'-15% 0px -55% 0px'});document.querySelectorAll('main>section[id]').forEach(s=>navObserver.observe(s));}
document.querySelector('.hero-art').setAttribute('role','group');
document.querySelector('#year').textContent=new Date().getFullYear();render();
new MutationObserver(()=>document.querySelectorAll('.vehicle-image[role="img"]:has(button)').forEach(el=>el.setAttribute('role','group'))).observe(grid,{childList:true,subtree:true});
document.querySelectorAll('.vehicle-image[role="img"]:has(button)').forEach(el=>el.setAttribute('role','group'));
import('./showroom.js').then(({initShowroom})=>initShowroom(vehicles.filter(v=>v.featured).slice(0,5),showVehicle));
import('./garage-game.js').then(({initGarageGame})=>initGarageGame());

})().catch(error=>{console.error(error);const notice=document.createElement('p');notice.textContent='No se pudo cargar el catálogo. Actualiza la página o comprueba que el sistema esté iniciado.';notice.style.cssText='padding:140px 30px;color:white';document.querySelector('.hero').replaceChildren(notice);});
